const Music = {
  playing: false, song: null, startAt: 0, cur: [], dcur: 0, master: null, noise: null,
  start(song, delay, offset) {                    // offset : on démarre la chanson à cet instant (secondes)
    const c = Sfx.ctx; this.playing = false; if (!c) return false;
    this.song = song; this.startAt = c.currentTime + (delay || 0) - (offset || 0); this.cur = song.tracks.map(() => 0); this.dcur = 0;
    if (!this.master) { this.master = c.createGain(); this.master.connect(c.destination); }
    this.master.gain.cancelScheduledValues(0); this.master.gain.value = Sfx.muted ? 0 : 0.9;
    if (!this.noise) { const b = c.createBuffer(1, c.sampleRate, c.sampleRate), d = b.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; this.noise = b; }
    this.playing = true; return true;
  },
  time() { const c = Sfx.ctx; return c.currentTime - (c.outputLatency || c.baseLatency || 0) - this.startAt; },     // temps réellement ENTENDU (latence de sortie déduite) : les flèches restent synchro
  stop() { if (this.playing && this.master) { this.master.gain.cancelScheduledValues(0); this.master.gain.setTargetAtTime(0, Sfx.ctx.currentTime, 0.05); } this.playing = false; },
  update() {                                    // à appeler à chaque image : programme les notes des 1,2 prochaines secondes
    if (!this.playing) return;
    const c = Sfx.ctx, now = this.time(), ahead = now + 1.2, S = this.song;
    this.master.gain.value = Sfx.muted ? 0 : (now > S.length - 1.5 ? Math.max(0, (S.length - now) / 1.5) * 0.9 : 0.9);
    S.tracks.forEach((tr, i) => {
      while (this.cur[i] < tr.n.length && tr.n[this.cur[i]][0] / 1000 < ahead) {
        const [t, d, note, vel] = tr.n[this.cur[i]++], t0 = this.startAt + t / 1000; if (t0 < c.currentTime - 0.05) continue;
        const o = c.createOscillator(), g = c.createGain(), v = tr.v * (0.5 + vel / 254), dur = d / 1000;
        o.type = tr.w; o.frequency.value = 440 * Math.pow(2, (note - 69) / 12);
        g.gain.setValueAtTime(0.0001, t0);
        if (tr.p === 'pluck') { g.gain.linearRampToValueAtTime(v, t0 + 0.005); g.gain.exponentialRampToValueAtTime(0.0001, t0 + Math.min(0.5, dur + 0.15)); }
        else if (tr.p === 'pad') { g.gain.linearRampToValueAtTime(v, t0 + 0.08); g.gain.setValueAtTime(v, t0 + Math.max(0.09, dur - 0.05)); g.gain.linearRampToValueAtTime(0.0001, t0 + dur + 0.2); }
        else { g.gain.linearRampToValueAtTime(v, t0 + 0.01); g.gain.setValueAtTime(v, t0 + Math.max(0.02, dur - 0.04)); g.gain.linearRampToValueAtTime(0.0001, t0 + dur + 0.06); }
        o.connect(g); g.connect(this.master); o.start(t0); o.stop(t0 + dur + 0.35);
      }
    });
    while (this.dcur < S.drums.length && S.drums[this.dcur][0] / 1000 < ahead) { const [t, k] = S.drums[this.dcur++]; const t0 = this.startAt + t / 1000; if (t0 >= c.currentTime - 0.05) this.drum(k, t0); }
  },
  drum(k, t0) {
    const c = Sfx.ctx, g = c.createGain(); g.connect(this.master);
    if (k === 'k') { const o = c.createOscillator(); o.frequency.setValueAtTime(150, t0); o.frequency.exponentialRampToValueAtTime(42, t0 + 0.12); g.gain.setValueAtTime(0.5, t0); g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.16); o.connect(g); o.start(t0); o.stop(t0 + 0.2); return; }
    const n = c.createBufferSource(); n.buffer = this.noise; const f = c.createBiquadFilter();
    if (k === 's') { f.type = 'bandpass'; f.frequency.value = 1900; g.gain.setValueAtTime(0.32, t0); g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.16); }
    else if (k === 'o') { f.type = 'highpass'; f.frequency.value = 6500; g.gain.setValueAtTime(0.1, t0); g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.2); }
    else if (k === 'h') { f.type = 'highpass'; f.frequency.value = 7500; g.gain.setValueAtTime(0.075, t0); g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.05); }
    else { f.type = 'highpass'; f.frequency.value = 5000; g.gain.setValueAtTime(0.03, t0); g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.04); }
    n.connect(f); f.connect(g); n.start(t0); n.stop(t0 + 0.25);
  },
};
